                int index = indexes[i];
                if (index != -1) {
                    FieldMapping field = fieldOrder[index];
                    newFieldOrder[i] = field;
                }
            }

            fieldOrder = newFieldOrder;
        }
    }

    readOrder = fieldOrder;
    initializeValuesForMissing();
